<?php declare(strict_types=1); ob_start();
require dirname(__DIR__).'/native/bootstrap.php';
require __DIR__.'/support/original-database-hash.php';
use Kulturhus\Native\TestSupport;
use Kulturhus\Native\Shared\{Access, Db};
use Kulturhus\Native\Cms\{Schema, Media, MediaMetadata, Pages, Conflict};
use Kulturhus\Native\Web\Website\PagePhotoStatus;
use Kulturhus\Native\Integration\{Endpoints, Routes};
$db=TestSupport::db();TestSupport::seed($db);Schema::install($db);$access=new Access($db,'admin');$checks=0;
function statusCheck(bool $ok,string $label):void {global $checks;if(!$ok)throw new RuntimeException($label);$checks++;echo 'PASS '.$label."\n";}
function statusReject(callable $fn,string $label,string $class=InvalidArgumentException::class):void {try{$fn();}catch(Throwable $e){statusCheck($e instanceof $class,$label);return;}throw new RuntimeException('Expected rejection: '.$label);}
$root=dirname(__DIR__,2).'/.local/page-photo-status-'.bin2hex(random_bytes(8));mkdir($root,0700,true);
$source=$root.'/own.png';$image=imagecreatetruecolor(36,24);imagefill($image,0,0,imagecolorallocate($image,25,110,175));imagepng($image,$source);unset($image);
$media=new Media($db,$access,$root.'/media');
$old=$media->upload($source,'Own exact original.png','Own original');
$other=(new Media($db,new Access($db,'editor'),$root.'/media'))->upload($source,'Other actor private.png','Other actor');
$foreign=(new Media($db,new Access($db,'outsider'),$root.'/media'))->upload($source,'Foreign private.png','Foreign secret');
$pages=new Pages($db,$access);$page=$pages->save(['title'=>'Own unchanged publication','slug'=>'own-status-publication','media_ids'=>[$old['id']]]);$page=$pages->publish($page['id'],$page['version']);$published=$pages->publicPage($page['slug']);
$service=new PagePhotoStatus($db,$access);$pending=bin2hex(random_bytes(16));
$orphan=bin2hex(random_bytes(16));$orphanDirectory=$root.'/media/'.hash('sha256',$access->club()).'/'.$orphan;mkdir($orphanDirectory,0700);copy($source,$orphanDirectory.'/original.png');
$snapshot=static function()use($db,$root):array{$files=[];foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root.'/media',FilesystemIterator::SKIP_DOTS))as$file)if($file->isFile())$files[$file->getPathname()]=hash_file('sha256',$file->getPathname());ksort($files);return [ownOriginalDatabaseHash($db,['native_users','native_grants','khcms_media','khcms_media_metadata','khcms_pages','khcms_revisions','khcms_published_media']),$files];};
$base=$snapshot();
statusCheck($service->query(['upload_id'=>$pending])===['found'=>false],'an uncommitted upload stays unconfirmed without replay or data');
statusCheck($service->query(['upload_id'=>$other['id']])===['found'=>false],'same-club another actor upload remains private');
statusCheck($service->query(['upload_id'=>$foreign['id']])===['found'=>false],'foreign upload exposes neither identity nor label');
statusCheck((new PagePhotoStatus($db,new Access($db,'outsider')))->query(['upload_id'=>$old['id']])===['found'=>false],'another club cannot recover an original owned upload');
statusReject(fn()=>(new PagePhotoStatus($db,new Access($db,'reader')))->query(['upload_id'=>$old['id']]),'reader cannot inspect an editor upload',DomainException::class);
statusCheck($snapshot()===$base,'missing and denied status reads preserve every original row and file');
foreach([null,[], '',str_repeat('a',31),str_repeat('a',33),str_repeat('A',32),'../own','ä',str_repeat('f',5000)]as$bad)statusReject(fn()=>$service->query(['upload_id'=>$bad]),'malformed exact upload lookup rejected');
foreach(['',str_repeat('a',31),str_repeat('A',32),'../own']as$bad)statusReject(fn()=>$media->upload($source,'Bad proposal.png','',null,null,$bad),'malformed upload proposal makes no image');
statusCheck($snapshot()===$base,'invalid lookup and upload identifiers preserve original bytes');
statusReject(fn()=>$media->upload($source,'Cannot replace orphan.png','',null,null,$orphan),'existing unregistered directory cannot be overwritten or cleaned',RuntimeException::class);
statusCheck($snapshot()===$base&&$service->query(['upload_id'=>$orphan])===['found'=>false],'unregistered original file remains byte-identical and reveals no upload status');
$copy=$media->upload($source,'Own newly uploaded Ä.png','',null,static function($row)use($pending,$pages,$page){if($row['id']!==$pending||$pages->get($page['id'])['version']!==2)throw new RuntimeException('Exact original association boundary required.');},$pending);
statusCheck($copy['id']===$pending,'actual upload uses the exact preassigned random identifier');
$result=$service->query(['upload_id'=>$pending]);
statusCheck($result===['found'=>true,'image'=>['id'=>$pending,'alt'=>'Own newly uploaded Ä','name'=>'Own newly uploaded Ä.png','url'=>'/media-preview/'.$pending.'/thumb','edit_url'=>'/?view=media&section=library&item='.$pending]],'read status returns the exact caller photo and compact private preview');
statusCheck(!str_contains(json_encode($result),$root)&&!isset($result['image']['sha256']),'status exposes no paths, full variants or unrelated private metadata');
$metadata=(new MediaMetadata($db,$access))->get($pending);
statusCheck($metadata['version']===0&&$metadata['rights_state']==='unknown'&&!$metadata['has_proof'],'recovery does not manufacture rights or proof');
statusCheck($pages->get($page['id'])===$page&&$pages->publicPage($page['slug'])===$published,'uploaded and recovered photo never joins or publishes the original page');
statusCheck($media->publicVariant($pending,'thumb')===null,'recovered actual photo remains private');
$derivedPending=bin2hex(random_bytes(16));$derived=$media->upload($source,'Own derived copy.png','',$old['id'],null,$derivedPending);
$derivedVariants=json_decode(Db::run($db,'SELECT variants_json FROM khcms_media WHERE id=?',[$derivedPending])->fetchColumn(),true,32,JSON_THROW_ON_ERROR);
statusCheck($derived['id']===$derivedPending&&$derivedVariants['original']['derived_from']===['media_id'=>$old['id'],'sha256'=>$old['sha256']],'preassigned derived upload retains the exact original source identity and hash');
statusCheck($service->query(['upload_id'=>$derivedPending])['image']['id']===$derivedPending&&$media->publicVariant($derivedPending,'thumb')===null,'read-only lookup finds the exact private derived copy');
statusCheck($pages->get($page['id'])===$page&&$pages->publicPage($page['slug'])===$published,'recovered derived copy changes no original association or publication');
$after=$snapshot();
foreach([$pending,$old['id'],$other['id'],$foreign['id']]as$id){$service->query(['upload_id'=>$id]);statusReject(fn()=>$media->upload($source,'Must not overwrite.png','',null,null,$id),'duplicate or foreign proposal cannot overwrite any original',Conflict::class);}
statusCheck($snapshot()===$after,'duplicate proposals and repeated status reads preserve all exact stored rows and variant bytes');
$failed=bin2hex(random_bytes(16));statusReject(fn()=>$media->upload($source,'Own rollback.png','',null,static function(){throw new RuntimeException('Own association rejection');},$failed),'failed association cannot leave a recoverable upload',RuntimeException::class);
statusCheck($service->query(['upload_id'=>$failed])===['found'=>false]&&$snapshot()===$after,'rolled-back upload leaves no row or owned variant directory');
$_SERVER['REQUEST_METHOD']='GET';http_response_code(200);ob_start();Endpoints::serve($db,$access,$root.'/media','own-csrf',['native_endpoint'=>'page-photo-status','upload_id'=>$pending]);$json=json_decode(ob_get_clean(),true,64,JSON_THROW_ON_ERROR);
statusCheck(http_response_code()===200&&$json['image']['url']===Routes::endpoint('media-preview',['media'=>$pending,'variant'=>'thumb']),'embedded lookup translates the exact original private thumbnail');
statusCheck($json['image']['edit_url']==='/vereinsverwaltung/?view=website&tab=gallery&native_item='.$pending.'&section=library','embedded lookup links only the exact private owned photo');
$_SERVER['REQUEST_METHOD']='HEAD';http_response_code(200);ob_start();Endpoints::serve($db,$access,$root.'/media','own-csrf',['native_endpoint'=>'page-photo-status','upload_id'=>$pending]);$body=ob_get_clean();statusCheck(http_response_code()===200&&$body==='','HEAD reads the actual status without a response body');
$_SERVER['REQUEST_METHOD']='POST';http_response_code(200);ob_start();Endpoints::serve($db,$access,$root.'/media','own-csrf',['native_endpoint'=>'page-photo-status','upload_id'=>$pending]);$body=ob_get_clean();statusCheck(http_response_code()===405&&$body==='','status rejects mutation methods without replay');
$_SERVER['REQUEST_METHOD']='GET';http_response_code(200);
Db::run($db,'DELETE FROM native_grants WHERE actor_id=? AND module=? AND capability=?',['admin','website','edit']);statusReject(fn()=>$service->query(['upload_id'=>$pending]),'immediate upload-edit revocation protects status',DomainException::class);Db::run($db,'INSERT INTO native_grants(actor_id,module,capability) VALUES(?,?,?)',['admin','website','edit']);
statusCheck($snapshot()===$after&&$pages->publicPage($page['slug'])===$published,'all status and failure cases preserve original publications, files and restored grants');
echo json_encode(['suite'=>'native-page-photo-status','checks'=>$checks,'external_requests'=>0])."\n";
